// Checkout.test.tsx
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartContext } from './CartContext';
import { PaymentContext } from './PaymentContext';

// Test fixtures - the Sumerian clay tablets of our age
const mockItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

const mockCartContext = {
  items: mockItems,
  total: 79.98,
  clearCart: vi.fn()
};

const mockProcessPayment = vi.fn();

const renderCheckout = (cartOverrides = {}, onComplete = vi.fn()) => {
  return render(
    <CartContext.Provider value={{ ...mockCartContext, ...cartOverrides }}>
      <PaymentContext.Provider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={onComplete} onCancel={vi.fn()} />
      </PaymentContext.Provider>
    </CartContext.Provider>
  );
};

describe('Checkout - Happy Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    renderCheckout({}, onComplete);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Babylon St');
    await user.type(screen.getByLabelText(/city/i), 'Uruk');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Gilgamesh');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/123 Babylon St/)).toBeInTheDocument();
    expect(screen.getByText(/1111/)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await screen.findByRole('status');
    expect(screen.getByText(/ORD-12345/)).toBeInTheDocument();
    expect(onComplete).toHaveBeenCalledWith('ORD-12345');
  });
});

describe('Checkout - Validation', () => {
  it('displays shipping errors for empty required fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    renderCheckout({ items: [], total: 0 });

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('handles payment failure with retry capability', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ... navigate to review step, then:

    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});
